#!/usr/bin/env python3
"""Build the private relay page (one copy button per generated file) used to paste the Power Apps build into Studio."""
import pathlib, html, sys
root=pathlib.Path(__file__).resolve().parent.parent; pa=root/'pa'; dest=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else '/home/claude/pa-relay'); dest.mkdir(exist_ok=True)
items=[('formulas',(pa/'formulas.fx').read_text()),('all-screens',(pa/'all-screens.yaml').read_text())]+[(f.stem,f.read_text()) for f in sorted((pa/'screens').glob('*.yaml'))]
h=['<!DOCTYPE html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DAM Policy Explorer: Power Apps build files</title>',
'<style>body{font:16px/1.4 system-ui,sans-serif;margin:16px;color:#1b1b1b;background:#fff}button{display:block;width:100%;max-width:520px;height:36px;margin:0 0 6px;font:inherit;font-weight:600;background:#0b55a3;color:#fff;border:0;border-radius:6px;cursor:pointer}button:focus-visible{outline:4px solid #ffd21f}textarea{position:absolute;left:-9999px}#s{font-weight:600;margin:8px 0 12px}</style></head><body>',
'<h1 style="font-size:20px;margin:0 0 4px">Power Apps build files</h1><p style="margin:0">Generated by tools/powerapp.py. Each button copies one file to the clipboard for pasting into Power Apps Studio.</p><p id="s" role="status">Nothing copied yet.</p>',
'<label for="v" style="display:block;font-weight:600">Check: paste a screen copied from Studio here to compare it with the build</label><textarea id="v" rows="1" style="position:static;width:100%;max-width:520px;height:34px;font:inherit;border:2px solid #1b1b1b;border-radius:4px"></textarea><pre id="r" role="status" style="white-space:pre-wrap;font:13px/1.35 ui-monospace,monospace;margin:6px 0 12px;max-width:900px">Nothing checked yet.</pre>']
for k,v in items: h.append(f'<button type="button" data-k="{k}">Copy {k} ({len(v):,} characters)</button><textarea id="t-{k}" aria-hidden="true" tabindex="-1" readonly>{html.escape(v)}</textarea>')
h.append(r"""<script>document.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){var t=document.getElementById('t-'+b.dataset.k);t.select();var ok=false;try{ok=document.execCommand('copy')}catch(e){}document.getElementById('s').textContent=(ok?'Copied ':'Could not copy ')+b.dataset.k+' ('+t.value.length+' characters)';window.getSelection().removeAllRanges();b.focus()})});
function parse(t){var o={},cur='(screen)',prop=null,m;o[cur]={};t.split(/\r?\n/).forEach(function(l){
 if(m=/^\s*- ([A-Za-z0-9_]+):\s*$/.exec(l)){cur=m[1];o[cur]={};prop=null}
 else if(m=/^\s{2}([A-Za-z0-9_]+):\s*$/.exec(l)){cur='(screen)';o.__name=m[1];prop=null}
 else if(m=/^\s*([A-Za-z]+): [|>][-+]?\s*$/.exec(l)){prop=m[1];o[cur][prop]=''}
 else if(m=/^\s*([A-Za-z]+): (=.*)$/.exec(l)){o[cur][m[1]]=m[2];prop=null}
 else if(/^\s*(Properties|Children|Screens):\s*$/.test(l)||/^\s*(Control|Variant|Layout|Group|IsLocked|MetadataKey): /.test(l)){prop=null}
 else if(prop){o[cur][prop]+=l}});return o}
function norm(x){return String(x==null?'':x).replace(/\s+/g,'')}
document.getElementById('v').addEventListener('paste',function(e){e.preventDefault();var got=parse((e.clipboardData||window.clipboardData).getData('text')),name=got.__name,r=document.getElementById('r');
 var src=document.getElementById('t-all-screens').value,exp=null;src.split(/^(?=  [A-Za-z0-9_]+:\s*$)/m).forEach(function(part){var q=parse(part);if(q.__name===name)exp=q});
 if(!exp){r.textContent='Pasted text is not one of the build screens (found: '+name+')';return}
 var diff=[],miss=0,n=0,c=0;Object.keys(exp).forEach(function(k){if(k==='__name')return;c++;if(!got[k]){diff.push(k+': control missing in Studio');return}
  Object.keys(exp[k]).forEach(function(pn){n++;if(!(pn in got[k])){miss++;if(/^(X|Y|Width|Height|Visible|OnSelect|Text|Items)$/.test(pn))diff.push(k+'.'+pn+': not in Studio copy (build '+norm(exp[k][pn]).slice(0,70)+')');return}
   if(norm(got[k][pn])!==norm(exp[k][pn]))diff.push(k+'.'+pn+': build '+norm(exp[k][pn]).slice(0,90)+' | Studio '+norm(got[k][pn]).slice(0,60))})});
 var extra=Object.keys(got).filter(function(k){return k!=='__name'&&!exp[k]});
 r.textContent=name+': '+c+' controls, '+n+' properties compared, '+diff.length+' differences, '+miss+' properties left at default by Studio, '+extra.length+' extra controls'+(diff.length?'\n'+diff.slice(0,60).join('\n'):'')+(extra.length?'\nextra: '+extra.slice(0,20).join(', '):'')})
</script></body></html>""")
(dest/'index.html').write_text(''.join(h)); print('relay', len(''.join(h)))
